function FriendsTab({ tab, onMessage, onAdd }: any) {
  const { data: friends = [] } = useFriends();
  const { data: pending = [] } = usePendingFriends();
  const filtered = tab === 'online' ? friends.filter(f => f.status !== 'offline')
    : tab === 'pending' ? []
    : tab === 'blocked' ? []
    : friends;
  return (
    <div style={{ flex: 1, overflowY: 'auto' }}>
      <div style={{ paddingInline: 16, paddingTop: 14, paddingBottom: 8, position: 'sticky', top: 0, background: 'var(--bg-0)' }}>
        <div style={{ height: 32, background: 'var(--bg-1)', borderRadius: 6, border: '1px solid var(--border)', paddingInline: 10, display: 'flex', alignItems: 'center', gap: 8 }}>
          <Lu name="search" size={13} color="var(--fg-2)" />
          <input className="cjk t-body" placeholder="搜索好友" style={{ flex: 1, background: 'transparent', border: 'none', outline: 'none', color: 'var(--fg-0)' }} />
        </div>
        <div className="cjk t-tag" style={{ color: 'var(--fg-2)', marginTop: 14 }}>
          {tab === 'online' ? `在线 — ${filtered.length}` : tab === 'all' ? `所有好友 — ${friends.length}` : tab === 'pending' ? `待处理 — ${pending.length}` : '已屏蔽 — 0'}
        </div>
      </div>
      {tab === 'pending' ? pending.map(p => <FriendRow key={p.handle} f={p} kind="pending" />) : filtered.map(f => <FriendRow key={f.handle} f={f} onMessage={() => onMessage(f.handle)} />)}
      {tab === 'blocked' && (
        <div style={{ padding: 40, textAlign: 'center' }}>
          <div className="cjk t-body" style={{ color: 'var(--fg-2)' }}>没有屏蔽任何人</div>
        </div>
      )}
    </div>
  );
}

