type DMProps = {
  theme?: 'dark' | 'light';
  view?: 'friends' | 'dm';
  peer?: string;
  onNavigate?: (target: { name: string; [k: string]: any }) => void;
  onToast?: (msg: { tone?: string; title: string; body?: string }) => void;
};

function DM({ theme = 'dark', view = 'friends', peer, onNavigate, onToast }: DMProps) {
  const { data: friends = [] } = useFriends();
  const peerObj = peer ? friends.find(f => f.handle === peer) || friends[1] : friends[1];
  const nav = (t: any) => onNavigate && onNavigate(t);
  const stub = (label: string) => onToast && onToast({ tone: 'info', title: label });
  return (
    <div className={`thp theme-${theme} anim-page-in`} style={{ width: '100%', height: '100%', display: 'flex', background: 'var(--bg-0)', overflow: 'hidden', borderRadius: 'var(--r-lg)' }}>
      <RailD active="dm" onPick={(p: string) => {
        if (p === 'home') nav({ name: 'lobby' });
        else if (p === 'settings') nav({ name: 'settings' });
        else if (p === 'discover') stub('发现');
        else if (p === 'add-server') stub('添加服务器');
        else nav({ name: 'lobby', gameId: p });
      }} />
      <DMSidebar activeId={view === 'dm' ? (peerObj && peerObj.handle) : null} onPick={(handle: string | null) => {
        if (!handle) nav({ name: 'dm', view: 'friends' });
        else nav({ name: 'dm', view: 'dm', peer: handle });
      }} />
      {view === 'dm' && peerObj
        ? <DMThread peer={peerObj} onPin={() => stub('置顶对话')} onAddUser={() => stub('邀请进群聊')} />
        : <FriendsHome active="online" onMessage={(handle: string) => nav({ name: 'dm', view: 'dm', peer: handle })} onAddFriend={() => stub('添加好友')} />}
    </div>
  );
}

export { DM };
